style.css:
@-moz-document domain("youtube.com") {
:root {
    -yt-spec-base-background: #fff7f5 !important; /* لون الخلفية الرئيسي (أبيض مائل للوردي الفاتح) */
    -yt-spec-text-primary: #370808 !important; /* لون النص الأساسي (بني داكن مائل للأحمر) */
    -yt-spec-text-secondary: #8b3c46 !important; /* لون النص الثانوي (بني متوسط مائل للأحمر) */
    -yt-spec-icon-active-other: #a74a57 !important; /* لون الأيقونات النشطة (بني فاتح مائل للأحمر) */
    -yt-spec-button-primary: #f9dddd !important; /* لون الأزرار الرئيسية (وردي فاتح جدًا) */
    -yt-spec-button-primary-text: #370808 !important; /* لون نص الأزرار الرئيسية (نفس لون النص الأساسي) */
    -yt-spec-brand-button-background: #f9dddd !important; /* لون خلفية أزرار العلامة التجارية */
    -yt-spec-brand-button-foreground: #370808 !important; /* لون مقدمة أزرار العلامة التجارية */
    -yt-spec-general-background-a: #f2e6e3 !important; /* لون خلفية عام ثانوي */
    -yt-spec-general-background-b: #e8d0cc !important; /* لون خلفية عام ثانوي آخر */
    -yt-spec-border-opaque: #d3b3b0 !important; /* لون الحدود */
  }

  /* تعديلات إضافية لبعض العناصر */
  ytd-thumbnail a:hover img {
    opacity: 0.8;
  }

  ytd-topbar {
    background-color: #e8d0cc !important; /* لون شريط التنقل العلوي */
  }

  #masthead-search-terms {
    background-color: #fff7f5 !important; /* لون خلفية مربع البحث */
    color: #370808 !important; /* لون النص في مربع البحث */
  }

  .ytd-video-primary-info-renderer {
    color: #370808 !important; /* لون معلومات الفيديو الأساسية */
  }

  .ytp-chrome-controls {
    background: rgba(232, 208, 204, 0.8) !important; /* لون خلفية أزرار تحكم الفيديو مع شفافية */
  }

  .ytp-progress-bar-container {
    background-color: #f9dddd !important; /* لون خلفية شريط تقدم الفيديو */
  }

  .ytp-play-progress {
    background-color: #a74a57 !important; /* لون الجزء الذي تم تشغيله من شريط التقدم */
  }

  .ytp-volume-slider-handle {
    background-color: #a74a57 !important; /* لون مؤشر التحكم في مستوى الصوت */
  }

  .yt-simple-endpoint.style-scope.ytd-button-renderer,
  .yt-simple-endpoint.style-scope.yt-formatted-string {
    color: #8b3c46 !important; /* لون الروابط والنصوص التفاعلية */
  }
}
